 ap=argparse.ArgumentParser();ap.add_argument('--cases',type=int,default=100000);ap.add_argument('--tail',type=int,default=10000);ap.add_argument('--seed',type=int,default=883);a=ap.parse_args();cached={f:check(f) for f in FAMILIES};failures=[f for f,v in cached.items() if not v];covered={FAMILIES[i%len(FAMILIES)] for i in range(a.cases)};tail_new={FAMILIES[(a.cases+i)%len(FAMILIES)] for i in range(a.tail)}-covered;status='PASS' if not failures and not tail_new and len(covered)==len(FAMILIES) else 'FAIL';print(json.dumps({'schema':'ikant-managed-local-runtime-stress/v0.23-test','status':status,'cases':a.cases,'tail':a.tail,'seed':a.seed,'families':len(FAMILIES),'failures':failures,'tail_new_families':sorted(tail_new)},sort_keys=True));return 0 if status=='PASS' else 1
